SELECT * FROM ${table}
WHERE tenant_id = #{tenantId} AND deleted = 0
ORDER BY id DESC LIMIT 500

SELECT * FROM ${table}
WHERE tenant_id = #{tenantId} AND id = #{id} AND deleted = 0
LIMIT 1

SELECT 1 FROM ${table}
WHERE tenant_id = #{tenantId} AND ${column} = #{id} AND enabled = 1 AND deleted = 0
LIMIT 1

