UPDATE ${mutation.table}
SET updated_by = #{mutation.actorId}, updated_at = CURRENT_TIMESTAMP(3),
    version = version + 1,
${field.column} = #{field.value}
WHERE tenant_id = #{mutation.tenantId} AND id = #{mutation.id}
  AND version = #{mutation.version} AND deleted = 0
